registerRefData('nsw-cond-n-5665',{"id":5665,"pan":null,"ref":"LDA2018/0269","address":"112 Talavera Road, Macquarie Park","description":"112 Talavera","outcome":null,"outcome_raw":"","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2018SNH038!20190620T064917.499 GMT","sha256":"2181f003bc6edad0121ea5d7b8da3cc0c5f7eb49cd3259f990dd5c5a4bb805a9","pages":75,"layout":"numbered","n":13,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/5665.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/112-talavera","lga":"RYDE","conditions":[{"label":"1","code":null,"number":"1","title":"Eucalyptus botryoides","text":"Bangalay","stage":"general","stage_basis":"heading","page":34},{"label":"2","code":null,"number":"2","title":"Callistemon viminalis","text":"Weeping Bottlebrush","stage":"general","stage_basis":"heading","page":34},{"label":"3","code":null,"number":"3","title":"Callistemon viminalis","text":"Weeping Bottlebrush","stage":"general","stage_basis":"heading","page":34},{"label":"5","code":null,"number":"5","title":"Eucalyptus botryoides","text":"Bangalay","stage":"general","stage_basis":"heading","page":34},{"label":"6","code":null,"number":"6","title":"Callistemon viminalis","text":"Weeping Bottlebrush","stage":"general","stage_basis":"heading","page":34},{"label":"8","code":null,"number":"8","title":"Casuarina glauca","text":"Swamp She-Oak","stage":"general","stage_basis":"heading","page":34},{"label":"9","code":null,"number":"9","title":"Casuarina glauca","text":"Swamp She-Oak","stage":"general","stage_basis":"heading","page":34},{"label":"10","code":null,"number":"10","title":"Casuarina cunninghamiana","text":"River Oak","stage":"general","stage_basis":"heading","page":34},{"label":"11","code":null,"number":"11","title":"Corymbia maculata","text":"Spotted Gum\nTree No. Species\n“Common name”","stage":"general","stage_basis":"heading","page":34},{"label":"12","code":null,"number":"12","title":"Eucalyptus microcorys","text":"Tallowood\n16 Phoenix canariensis\nCanary Island Date Palm\n127. Project Arborist. A Project Arborist with minimum AQF level 5 qualifications is\nto be engaged to ensure adequate tree protection measures are put in place for\nall trees to be retained on adjoining allotments in accordance with AS4970-\n2009 Protection of trees on development sites. All trees are to be monitored to\nensure adequate health throughout t he construction period. Addi tionally, all\nwork within the Tree Protection Zones is to be supervised by th e Project\nArborist throughout construction.\n128. Provision of Project Arborist details. Council is to be notified, in writing, of\nthe name, contact details and qualif ications of the Project Arb orist appointed to\nthe site. Should these details change during the course of work s, or the\nappointed Consultant Arborist al ter, Council is to be notified, in writing, within\nseven working days.\n129. Tree Protection. All tree protection works includ ing installation of any fencing\nis to be undertaken prior to any demolition, site clearing or c onstruction works\non site.\n130. Tree Protection Fencing. All trees to be retained on site and on adjoining site\nare to have protective fencing and signage around TPZs and must be located in\naccordance with AS4970: Protecti on of trees on development site s. In this\nregard, any fencing required to be constructed around the TPZ i s to be in\naccordance with AS4687 Temporary f encing and hoardings. Tree Pr otective\nFencing is to be installed befor e demolition and construction c ommences as\nindicated in the Arborist Report in Section 4 Recommendations p repared by\nSturt Noble dated 16/11/2018 amended\n131. Arborist Report Recommendations. All items in the Arborist Report outlined\nin the Arborist Report in Secti on 4 Recommendations prepared by Sturt Noble\ndated 16/11/2018 amended are to be implemented.\n132. Development to be within site boundaries. The development must be\nconstructed wholly within the boundaries of the premises. No p ortion of the\nproposed structure shall encroac h onto the adjoining properties . Any doors/\ngates on the boundary must be installed so they do not open onto any footpath.\n133. Property above/below Footpath Level. Where the ground level adjacent the\nproperty alignment is above/below t he ultimate footpath level, as set by\nCouncil, adequate measures are t o be taken (either by means of constructing\napproved retaining structures or batters entirely on the subjec t property) to\nsupport the subject land/footpath. An approved fence shall be erected along the\nboundary for public safety.\n134. Ground Anchors. The installation of permanent ground anchors into public\nroadway is not permitted. The in stallation of temporary ground anchors may be\nconsidered subject to application for approval from Council’s Civil Infrastructure\n& Integration Department, as per the provisions of Section 138 of the Roads\nAct. The application for consent must include detailed structur al plans prepared\nby a chartered structural enginee r, clearly nominating the numb er of proposed\nanchors, depth below existing ground level at the boundary alig nment and the\nangle of installation. Approval is subject to the applicant pay ing all applicable\nfees in accordance with Council’s Schedule of Fees and Charges.\n135. Notice of Intention to Commence Public Domain Works - Prior to\ncommencement of the public domain works, a Notice of Intention to Commence\nPublic Domain Works shall be submitted to Council’s City Works Directorate.\nThis Notice shall include the name of the Contractor who will be responsible for\nthe construction works, and the name of the Supervising Enginee r who will be\nresponsible for providing the ce rtifications required at the ho ld points during\nconstruction, and also obtain all Road Activity Permits required for the works.\nNote: Copies of a number of documents are required to be lodged with the\nNotice; no fee is chargeable for the lodgement of the Notice.\n136. Notification of adjoining owners & occupiers - public domain wo rks - The\nApplicant shall provide the adjoining owners and occupiers written notice of the\nproposed public domain works a minimum two weeks prior to comme ncement\nof construction. The notice is to include a contact person nam e and number\nshould adjoining owners and occupi ers have any enquiries in rel ation to the\nconstruction works. The duration of any interference to neighbouring driveways\nshall be minimised; and driveways shall be returned to the operational condition\nas they were prior to the commencement of works, at no cost to the owners.\n137. Pre-construction inspection - A joint inspection shall be undertaken with\nCouncil’s Engineer from City Works Directorate prior to commenc ement of any\napproved public domain works. A m inimum of 48 hours’ notice wil l be required\nwhen booking for the joint inspection.\n138. Pre-Construction Dilapidation Report - To ensure Council’s infrastructures are\nadequately protected a pre-construction dilapidation report on the existing public\ninfrastructure in the vicinity of the proposed development and along the travel\nroutes of all construction vehicles, up to 100m either side of the development site,\nis to be submitted to Council. T he report shall detail, but not be limited to, the\nlocation, description and photographic record (in colour) of an\ny observable defects\nto the following infrastructure where applicable.\n(a) Road pavement,\n(b) Kerb and gutter,\n(c) Footpath,\n(d) Drainage pits and lintels,\n(e) Traffic signs, and\n(f) Any other relevant infrastructure.\nThe report is to be dated and submitted to, and accepted by Council’s City Works\nDirectorate, prior to any work commencing.\nAll fees and charges associated with the review of this report shall be in\naccordance with Council’s Schedule of Fees and Charges and shall be paid at the\ntime that the Dilapidation Report is submitted.\n139. Road Activity Permits - To carry out work in, on or over a public road, the\nConsent of Council is required as per the Roads Act 1993 . Prior to the\ncommencement of the relevant works and considering the lead tim es required\nfor each application, permits for the following activities, as required and as\nspecified in the form \"Road Activity Permits Checklist\" (available from Council’s\nwebsite) are to be obtained and copies submitted to Council wit h the Notice of\nIntention to Commence Public Domain Works.\n(a) Road Use Permit - The applicant shall obtain a Road Use Per mit where\nany area of the public road or footpath is to be occupied as co nstruction\nworkspace, other than activities covered by a Road Opening Perm it or if a\nWork Zone Permit is not obtained. The permit does not grant exe mption\nfrom parking regulations.\n(b) Work Zone Permit - The applicant shall obtain a Work Zone P ermit where\nit is proposed to reserve an area of road pavement for the park ing of\nvehicles associated with a construction site. Separate applicat ion is\nrequired with a Traffic Management Plan for standing of constru ction\nvehicles in a trafficable lane. A Roads and Maritime Services Road\nOccupancy Licence shall be obtained for State Roads.\n(c) Road Opening Permit - The applicant shall apply for a road- opening\npermit and pay the required fee where a new pipeline is to be c onstructed\nwithin or across the road pavem ent or footpath. Additional road opening\npermits and fees are required where there are connections to pu blic utility\nservices (e.g. telephone, teleco mmunications, electricity, sewe r, water or\ngas) within the road reserve. No opening of the road or footpat h surface\nshall be carried out without this permit being obtained and a c opy kept on\nthe site.\n(d) Elevated Tower, Crane or Concrete Pump Permit - The applica nt shall\nobtain an Elevated Tower, Crane or Concrete Pump Permit where a ny of\nthese items of plant are place d on Council's roads or footpaths . This\npermit is in addition to either a Road Use Permit or a Work Zone Permit.\n(e) Crane Airspace Permit - The applicant shall obtain a Crane Over Airspace\nPermit where a crane on private land is operating in the air sp ace of a\nCouncil road or footpath. Approval from the Roads and Maritime Services\nfor works on or near State Roads is required prior to lodgement o f a n\napplication with Council. A separate application for a Work Zon e Permit is\nrequired for any construction vehicles or plant on the adjoinin g road or\nfootpath associated with use of the crane.\n(f) Hoarding Permit - The applicant shall obtain a Hoarding Per mit and pay\nthe required fee where erection of protective hoarding along th e street\nfrontage of the property is requir ed. The fee payable is for a minimum\nperiod of 6 months and should t he period is extended an adjustm ent of\nthe fee will be made on completion of the works. The site must be fenced\nto a minimum height of 1.8 metres prior to the commencement of\nconstruction and throughout demolit ion and/or excavation and mu st\ncomply with WorkCover (New South Wales) requirements.\n(g) Skip Bin on Nature Strip - The applicant shall obtain appro val and pay the\nrequired fee to place a Skip Bin on the nature strip where it is not practical\nto locate the bin on private property. No permit will be issued to place\nskips.\n140. Temporary Footpath Crossing - A temporary footpath crossing, if required,\nmust be provided at the vehicula r access points. The width of t emporary\ncrossing shall be determined by a swept path of the largest tru ck to access the\nsite. Application for any temporary driveway crossing must be submitted to\nCouncil with proposed constructi on design plans for approval pr ior to the issue\nof any Construction Certificate.\nAll fees and charges associated with the review of this submiss ion shall be in\naccordance with Council’s Schedule of Fees and Charges and shall be paid at the\ntime that the application is submitted.\n141. Ryde Traffic Committee Approval - A plan showing details of the proposed\nsignage and line marking, and/or traffic devices including pede strian refuge,\npedestrian crossing or LATM measures, shall be submitted to the Council and\napproved by the Ryde Traffic Committee prior to the installatio n of any traffic\ndevices, signage and line marking.\n142. Work Zones and Permits . Prior to commencement of the associated works,\nthe applicant shall obtain a Work Zone Permit where it is propo sed to reserve\nan area of road pavement for the parking of vehicles associated with a\nconstruction site. Separate application is required with a Traf fic Management\nPlan for standing of construction vehicles in a trafficable lan e. A Roads and\nMaritime Services Work Zone Permit shall be obtained for State Roads.\n143. Notice of Intention to Commence Trunk Drainage Works -\nPrior to\ncommencement of the trunk drainage works, a Notice of Intention t o\nCommence Trunk Drainage Works shall be submitted to Council’s C ity Works\nDirectorate. This Notice shall include the name of the Contract or who will be\nresponsible for the construction works, and the name of the Sup ervising\nEngineer who will be responsible f or providing the certificatio ns required at the\nhold points during construction, and also obtain all Road Activ ity Permits\nrequired for the works.\n144. Notification to adjacent properties - Trunk Drainage Works - The Applicant\nshall provide the adjoining owners and occupiers written notice of the proposed\ntrunk drainage works a minimum two weeks prior to commencement of\nconstruction. The notice is to include a contact person name a nd number\nshould adjoining owners and occupi ers have any enquiries in rel ation to the\nconstruction works. The duration of any interference to neighbo uring driveways\nshall be minimised; and driveways shall be returned to the operational condition\nas they were prior to the commencement of works, at no cost to the owners.\n145. Trunk drainage Construction Staging - A construction program that\nsequences the construction of the proposed trunk drainage works f r o m t h e\nupstream of Talavera Road and through the development site shal l be\nsubmitted to and approved by Council prior to the commencement of the trunk\ndrainage construction works. The program shall be adequately de tailed to\ninclude key dates for commencement, inspections, and completion.\n146. Pre-Construction CCTV Report - To ensure Council’s stormwater\ninfrastructures are adequately protected, a pre-construction CCTV report on the\nexisting Council stormwater infrastructure in the vicinity of t he proposed\ndevelopment is to be submitted to Council prior to the commence ment of any\nconstruction works.\nAn electronic closed circuit television report (track mounted CCTV camera\nfootage) prepared by an accredited operator that assesses the condition of the\nexisting Council stormwater infrastructure adjacent and within the site is\nrequired. This report shall include the date of CCTV inspection and shall be\nsubmitted to Council’s City Works Directorate for approval prior to\ncommencement of any works.\nThe applicant shall contact Council’s Stormwater and Catchments section to\nobtain a map of Council’s existing Stormwater network in the vicinity prior to\nconducting the CCTV survey.","stage":"general","stage_basis":"heading","page":35},{"label":"13","code":null,"number":"13","title":"Cupaniopsis anacardioides","text":"Tuckeroo","stage":"during_work","stage_basis":"heading","page":41},{"label":"14","code":null,"number":"14","title":"Cupaniopsis anacardioides","text":"Tuckeroo","stage":"during_work","stage_basis":"heading","page":41},{"label":"15","code":null,"number":"15","title":"Cupaniopsis anacardioides","text":"Tuckeroo\n157. Project Arborist Inspections. The Project Arborist is to inspect and document\nwith Certificates of Compliance to the certifying authority as stipulated in\nSECTION 5 MONITORING AND CERTIFICATION of AS4970-2009.\nPro\nject Phase Activities Pro ject Arborist To:\nInitial Site\nPreparation\nEstablish/delineate TPZ\nInstall protective measures\nand undertake soil\nrehabilitation for all trees to\nbe retained.\nProject Arborist to mark\nTree Protection Zones and\ninstall fences, mulch,\nirrigation and signage\nIssue a Certification of\nCompliance of tree\nprotection measures being\nin place and soil\nrehabilitation undertaken\nConstruction work Liaison with site manager,\ncompliance and any\ndeviation from approved\nplan\nMaintain or amend\nprotective measures\nSupervision and\nmonitoring formal\nnotification of any deviation\nfrom approved tree\nprotection plan\nStormwater\nconnection\ninstallation through\nTPZ, Implement\nhard and soft\nlandscape works\nSupervise Installation of\npipes within tree TPZ\nExcavate trench through\nTPZ under Arborist\nsupervision, install\npipework, remove selected\nprotective measures as\nnecessary and perform\nremedial tree works\nIssue a Certificate of\nCompliance\nPractical\nCompletion\nTree vigour and structure\nAssessment and\nundertake soil\nrehabilitation for all\nretained trees\nRemove all remaining tree\nProtection measures\nCertification of tree\nprotection and soil\nrehabilitation for\nProtected Trees\nProject Phase Activities Pro ject Arborist To:\nDefects liability /\nmaintenance period\nTree vigour and structure Undertake any required\nremedial tree works\nCertification of tree\nprotection if necessary\n158. Tree works - Australian Standards. Any works approved by this consent to\ntrees must be carried out in accordance with all relevant Australian Standards.\n159. Discovery of Additional Information - Council and the Principal Certifying\nAuthority (if Council is not the PCA) must be notified as soon as practicable if\nany information is discovered dur ing demolition or construction work that has\nthe potential to alter previous conclusions about site contamination.\n160. Identification and removal of hazardous materials - A n y h a z a r d o u s\nmaterials, including asbestos, must be identified before demoli tion work\ncommences and be removed in a safe manner.\n161. Storage and removal of wastes - All demolition and construction wastes must\nbe stored in an environmentally a cceptable manner and be remove d from the\nsite at frequent intervals to pr event any nuisance or danger to health, safety or\nthe environment.\n162. Contaminated soil - All potentially contaminat ed soil excavated during\ndemolition or construction work must be stockpiled in a secure area and be\nassessed and classified in accordance with the Waste Classification Guidelines\nPart 1: Classifying Waste (EPA, 2014) before being transported from the site.\n163. Transportation of wastes - All wastes must be transported in an\nenvironmentally safe manner to a facility or place that can lawfully be used as a\nwaste facility for those wastes. Copies of the disposal dockets must be kept by\nthe applicant for at least 3 years and be submitted to Council on request.\n164. Recyclable wastes - All wastes intended for recycling must be transported to a\nfacility where the wastes will be recycled or re-used.\n165. Disposal of asbestos wastes - All asbestos wastes must be disposed of at a\nlandfill facility licensed to receive asbestos waste.\n166. Imported fill - All imported fill must be valid ated in accordance with the\nContaminated Sites Sampling Design Guidelines (EPA, 1995) by an\nexperienced environmental consultant, and a copy of the validat ion report must\nbe submitted to the Principal Ce rtifying Authority (and Council , if Council is not\nthe PCA) before the fill is used.\n167. Use of fill/excavated material. Excavated material must not be reused on the\nproperty except as follows:\n(a) Fill is allowed under this consent;\n(b) The material constitutes Virgin Excavated Natural Material as defined in\nthe Protection of the Environment Operations Act 1997;\n(c) the material is reused only to the extent that fill is allowed by the consent.\nAll surplus excavated material must be disposed of at a license d landfill facility,\nunless Council approves an alternative disposal site.\n168. Traffic Management. Any traffic management pro cedures and systems must\nbe in accordance with AS 1742.3 1996 and City of Ryde, Development Control\nPlan 2014: - Part 8.1; Construction Activities. This condition is to ensure public\nsafety and minimise any impacts to the adjoining pedestrian and vehicular\ntraffic systems.\n169. Truck Shaker. A truck shaker grid with a minimum length of 6 metres must be\nprovided at the construction exit point. Fences are to be erect ed to ensure\nvehicles cannot bypass them. S ediment tracked onto the public r oadway by\nvehicles leaving the subject site is to be swept up immediately.\n170. Stormwater Management - Construction. The stormwater drainage system\non the site must be constructed in accordance with the Construction Certificate\nversion of the Stormwater Management Plan by AT&L Civil Engineers (Refer to\nProject No. 16-428 Dwgs DAC001 (F ), DAC002 (F), DAC004 (A), DAC 010 (G),\nDAC011 (G), DAC012 (F),DAC013 (F), DAC014 (F), DAC015 (F), DAC023 (E),\nDAC024 (C) & DA050 (A)) submitted in compliance to the conditio n labelled\n“Stormwater Management.” and the requirements of Council in rel ation to the\nconnection to the public drainage system.\n171. Erosion and Sediment Control. The applicant shall install erosion and\nsediment control measures in a ccordance with the approved plan at the\ncommencement of works on the site . Suitable erosion control ma nagement\nprocedures in accordance with the manual “Managing Urban Stormw ater: Soils\nand Construction“ by the NSW D epartment - Office of Environment a n d\nHeritage, must be practiced at all times throughout the constru ction. Where\nconstruction works deviate from the plan, soil erosion and sedi ment control\nmeasures are to be implemented in accordance with the above ref erenced\ndocument.\n172. Construction Waste. Tip Dockets identifying the type and quantity of waste\ndisposed/recycled during construction are to be kept in accorda nce with the\nSite Waste Minimisation & Management Plan for spot inspections.\n173. Maintenance of area around construction site. The area surrounding the\nconstruction site must be maintained to reduce the incidence of illegal dumping\nand management of litter from the site and workers associated w ith the site\nmust be undertaken.\n174. Hold Points during construction - Public Domain - Council requires\ninspections to be undertaken by a Chartered Civil Engineer (reg istered on the\nNER of Engineers Australia), for the public domain, at the hold points shown\nbelow.\nThe Applicant shall submit to C ouncil’s City Works Directorate, certification\nfrom the Engineer, at each stage of the inspection listed below , within 24 hours\nfollowing completion of the relev ant stage/s. The certificates shall contain\nphotographs of the works in progr ess and a commentary of the in spected\nworks, including any deficiencies and rectifications that were undertaken.\n(a) Prior to the commencement of construction and following the set-out on\nsite of the position of the civil works to the levels shown on the approved\ncivil drawings.\n(b) Upon excavation, trimming and compaction to the subgrade level - to the\nline, grade, widths and depths, shown on the approved civil engineering\ndrawings.\n(c) Upon compaction of the applicable sub-base course.\n(d) Upon compaction or constructi on of any base layers of pavement, prior to\nthe construction of the final pavement surface (e.g. prior to laying any\npavers or asphalt wearing course).\n(e) Upon installation of any fo rmwork and reinforcement for footpath concrete\nworks.\n(f) Final inspection - upon the practical completion of all civil works with all\ndisturbed areas satisfactorily restored.\n175. Implementation of Construction Pedestrian and Traffic Managemen t Plan.\nAll works and construction activities are to be undertaken in a ccordance with\nthe approved Construction Pedestrian and Traffic Management Pla n (CPTMP).\nAll controls in the CPTMP must be maintained at all times and a ll traffic\nmanagement control must be undertaken by personnel having appro priate\nRMS accreditation. Should the impl ementation or effectiveness o f the CPTMP\nbe impacted by surrounding major development not encompassed in t h e\napproved CPTMP, the CPTMP measures and controls are to be revis ed\naccordingly and submitted to Council for approval. A copy of th e approved\nCPTMP is to be kept onsite at all times and made available to t he accredited\ncertifier or Council on request.\n176. Hold Points during construction - Trunk Drainage Works - Council\nrequires inspections to be undertaken by a suitably qualified C hartered Civil\nEngineer (registered on the NER of Engineers Australia), or equ ivalent, for all\nCouncil trunk drainage works.\nThe Applicant shall submit to the Principal Certifying Authority, certification from\nthe Engineer, at each stage of t he inspection listed below, sta ting all civil and\nstructural construction works have been executed as detailed in t h e s t a m p e d\napproved plans, and in accordance with the relevant Australian Standards, City\nof Ryde standards and specificat ions within 24 hours following completion of\nthe relevant stage/s. The cert ificates shall contain photograph s of the works in\nprogress and a commentary of the in spected works, including any deficiencies\nand rectifications that were undertaken.\n(a) Upon excavation of trenches a s per the approved drainage drawings.\n(b) Upon installation of pit rei nforcement but prior to concrete pour for cast in-\nsitu pits.\n(c) Upon installation of pipes and other drainage structures prior to backfilling.\n(d) Upon backfilling of excavat ed areas and prior to the construction of the\nfinal pavement surface.\n(e) Final inspection - upon the pr actical completion of all drainage and\nassociated works (including road pavements, kerb & gutters, footpaths\nand driveways) with all disturbed areas satisfactorily restored.\nAny stormwater pit with a depth greater than 1.8 metres shall be certified by a\nsuitably qualified Structural Engineer.\nPRIOR TO OCCUPATION CERTIFICATE\nAn Occupation Certificate must be obtained from a Principal Certifying Authority prior\nto commencement of occupation of any part of the development, o r prior to the\ncommencement of a change of use of a building.\nPrior to issue, the Principal Ce rtifying Authority must ensure that all works are\ncompleted in compliance with t he approved construction certific ate plans and all\nconditions of this Development Consent.\nUnless an alternative approval aut hority is specified (eg Counc il or government\nagency), the Principal Certifying Authority is responsible for determining compliance\nwith conditions in this Part of the consent. Details to demonst rate compliance with all\nconditions, including plans, do cumentation, or other written ev idence must be\nsubmitted to the Principal Certifying Authority.\n177. BASIX. The submission of documentary ev idence of compliance with all\ncommitments listed in BASIX Ce rtificate(s) numbered 934519M_03, dated 17\nMay 2019.\n178. Landscaping. All landscaping works approv ed by condition 1 are to be\ncompleted prior to the issue of the any Occupation Certificate.\n179. Sydney Water - Section 73 Compliance Certificate. A compliance certificate\nmust be obtained from Sydney Wat er, under Section 73 of the Syd ney Water\nAct 1994. Sydney Water will determine the availability of water and sewer\nservices, which may require extension, adjustment or connection to Sydney\nWater mains. A Section 73 Compliance Certificate must be comple ted before\nthe issue of any Occupation Cert ificate. Sydney Water will asse ss the\ndevelopment and if required will i ssue a Notice of Requirements letter detailing\nall requirements that must be me t. Applications can be made eit her directly to\nSydney Water or through a Sydney Water accredited Water Servici ng\nCoordinator.\nGo to www.sydneywater.com.au/section73 or call 1300 082 746 to learn more\nabout applying through an authorised WSC or Sydney Water.\n180. Post-construction dilapidation report. The submission of a post-construction\ndilapidation report which clearly details the final condition o f all property,\ninfrastructure, natural and man -made features that were recorde d in the pre-\ncommencement dilapidation report. A copy of the report must be provided to\nCouncil, any other owners of publ ic infrastructure and the owne rs of the\naffected adjoining and private properties, prior to the issue o f any Occupation\nCertificate.\n181. Public domain - work-as-executed plan. A works as executed plan for works\ncarried out in the public domain must be provided to and endors ed by Council\nprior to the issue of any Occupation Certificate.\n182. Letterboxes and street/house numbering. All letterboxes and house\nnumbering are to be designed and c onstructed to be accessible from the public\nway. Council must be contacted in relation to any specific requ irements for\nstreet numbering. The applicant should liaise with Australia Po st and develop\nstrategies in relation to security of mail boxes.\n183. Swimming Pool Register. Legislation requires all swimming pools to be\nregistered online at: http:// www.swimmingpoolregister.nsw.gov.au/.\nDocumentary evidence confirming that the swimming pool has been registered\nmust be submitted to the Principal Certifying Authority prior to the issuing of any\nOccupation Certificate.\n184. Certification of fit-out work - Where Council is not the Principal Certifying\nAuthority, the PCA must inspect the completed fit-out and issue a compliance\ncertificate certifying that the fit-out complies with Food Safe ty Standard 3.2.3:\nFood Premises and Equipment and Australian Standard AS 4674-2004:\nDesign, construction and fit-out of food premises, and a copy of the compliance\ncertificate must be submitted to Council, before the issue of an Occupation\nCertificate.\n185. Compliance report - A r e p o r t f r o m a q u a l i f i ed acoustical consultant\ndemonstrating compliance with the relevant noise and vibration criteria must be\nsubmitted to the Principal Certifying Authority (and Council, if Council is not the\nPCA) before the issue of an Occupation Certificate.\n186. Public Art Plan. Prior to the issue of any Occupation Certificate , the\napproved works contained in the Public Art Plan approved by Condition 71 shall\nbe implemented.\n187. Acoustic Report. A report from a qualified acoustical consultant demonstrating\ncompliance with the relevant noise criteria including complianc e with the\nrecommendations contained in the Acoustic Report (Revision 2, R ef.\n20161723.2/2111A/R2/TA) prepared by A coustics Logic dated 21 No vember\n2018 must be submitted to the Prin cipal Certifying Authority before the issue of\nan Occupation Certificate.\n188. Design Verification. Prior to an Occupation Certificate being issued to\nauthorise a person to commence occupation or use of a residential flat building,\nthe Principal Certifying Author ity (PCA) is to be provided with a D e s i g n\nVerification from a qualified des igner. The statement must incl ude verification\nfrom a qualified designer that t he residential flat development achieves the\ndesign quality of the development shown on plans and specifications in respect\nto any Construction Certificate issued, having regard to the de sign quality\nprinciples set out in Schedule 1 of the State Environmental Pla nning Policy No\n65 - Design Quality of Residential Flat Development. This condition is imposed\nin accordance with Clause 154A of the Environmental Planning and\nAssessment Regulations 2000.\n189. CCTV Cameras. CCTV cameras will be required to be installed in the following\nlocations:\n All entry and exit poi nts to the building;\n The carpark;\n The ground floor lobby and lifts;\n The car park entry/exit points; and\n Level 5 child care centre entrance\nThe cameras should include the foyer area to the buildings incl uding the area\naround the mail boxes. The cameras should also monitor the 50 m etre vicinity\noutside the building including, but not limited to, the footpath area in front of the\npremises. CCTV cameras should also cover any communal areas, li fts, public\nspaces and the basement car parks. Recordings should be made tw enty four\n(24) hours a day seven (7) days a week.\nAs a minimum, CCTV cameras at ent ry and exit points to the prem ises MUST\nrecord footage of a nature and quality in which it can be used to identify a\nperson recorded by the camera. All other cameras MUST record fo otage of a\nnature and quality in which it can be used to recognise a person recorded by\nthe camera. The time and date mu st automatically be recorded on all\nrecordings made whilst it is reco rding. All recordings are to b e kept for a\nminimum period of thirty (30) days before they can be reused or destroyed.\nIf requested by police, the applicant is to archive any recordi ng until such time\nas they are no longer required. Recordings are to be made in a common media\nformat such as Windows Media Player or similar, or should be ac companied by\napplicable viewing software to enable viewing on any windows computer.\nDetails demonstrating compliance are to be submitted to the Principal Certifying\nAuthority prior to the issue of an Occupation Certificate.\n190. Car parking security . Vehicular entry to residential parking and visitor’s\nparking areas is to be through a secured roller shutter with an intercom system\nfor visitor’s access. The doors are to be controlled by lockset s such as remote\nor card operating electronic lo ck sets. The phasing of the roll er door needs to\nminimise the opportunity for unaut horised pedestrian access aft e r a v e h i c l e\nenters/exits the car park. Details demonstrating compliance are to be submitted\nto the Principal Certifying Aut hority prior to the issue of an Occupation\nCertificate.\n191. Graffiti. All surfaces on the street level that are not glass should use graffiti\nresistant paints and/or other sur faces that discourage graffiti . Details\ndemonstrating compliance are to be submitted to the Principal C ertifying\nAuthority prior to the issue of an Occupation Certificate.\n192. Security. To enhance the physical security of doors, all glass doors are to be\nlaminated and the main entry/exit doors to individual units on the ground floor,\nincluding balcony doors and fire exit doors to the development are to be fitted\nwith a single cylinder lockset (Australian and New Zealand Stan dard - Lock\nSets), which comply with the Bu ilding Code of Australia. Window s to individual\nunits on the ground floor should also be fitted with key operat ed locksets\n(Australia and New Zealand Standard - Lock Sets) to restrict un authorized\naccess to the unit.\nDetails demonstrating compliance are to be submitted to the Principal Certifying\nAuthority prior to the issue of an Occupation Certificate.\n193. Intercom System. Intercom facilities should be incorporated into these\nentry/exit points to enable residents to communicate and identi fy with people\nprior to admitting them to the development. An auxiliary lock s et should also be\nincorporated into the design of each of the entry/exit points t o enable\nemergency services to access the development particularly in em ergency\nsituations.\nDetails demonstrating compliance are to be submitted to the Principal Certifying\nAuthority prior to the issue of an Occupation Certificate.\n194. Balcony doors to units . Balcony doors to units are to be fitted with single\ncylinder locksets (Australian and New Zealand Standard - Lock S ets) to restrict\nunauthorised access to units. Details demonstrating compliance are to be\nsubmitted to the Principal Cert ifying Authority prior to the is sue of an\nOccupation Certificate.\n195. Lift access and security. Electronic access controls are to be installed on the\nlift. The equipment should include card readers to restrict acc ess to the level a\nresident resides on, to the car parking levels and to the Groun d Floor. Details\ndemonstrating compliance are to be submitted to the Principal C ertifying\nAuthority prior to the issue of an Occupation Certificate.\n196. Car Share Provider. The submission of documentary evidence to Council that\nan agreement with a car-share prov ider has been entered into fo r the eight car\nshare spaces on site, prior to the issue of any\nOccupation Certificate.\n197. Travel Place. A Framework Travel Plan (FTP) to be submitted to Council\ndetailing the promotion, develop ment, implementation and monito ring of a co-\nordinated transport strategy for the building The objectives of t h e F T P a r e t o\nencourage/provide incentives for residents to utilise public tr ansport, walking\nand cycling and to investigate alternative modes of transport ( away from single-\noccupancy car use) to more sustainable forms of transport and h ow the plans\nwill achieve and monitor the objec tives. The FTP is to be submi tted and\napproved by Council prior to the issue of an Occupation Certificate.\n198. Retail Parking Spaces. To ensure the provision of r etail parking spaces is in\naccordance with the DCP Part 9.3 (Parking Controls), all resident visitor spaces\nare to be configured so as to also accommodate retail customers.\n199. Stormwater Management - Work-as-Executed Plan. A Work-as-Executed\nplan (WAE) of the as construct ed Stormwater Management System m ust be\nsubmitted with the ap plication for an Occupation Certificate. T he WAE must be\nprepared and certified (signed a nd dated) by a Registered Surve yor and is to\nclearly show the constructed st ormwater drainage system (including any onsite\ndetention, pump/ sump, charged/ siphonic and onsite disposal/ a bsorption\nsystem) and finished surface levels which convey stormwater runoff.\n200. Stormwater Management - Maintenance program. To ensure the approved\nWSUD measures function as designed for the ongoing life of the development,\nwithout imposition on the public domain, the applicant is to pr epare a drainage\nsystem maintenance plan (DSMP) which is to contain;\n(a) The DSMP is to incorporate a master schedule and plan identifying the\nlocation of all stormwater components crucial to the efficient operation of\nthe trunk drainage system on the development lot. This is to include (but\nnot be limited to) pump/sump systems, WSUD components and any\nonsite detention systems. The master plan is also to contain the\nmaintenance schedule for each component.\n(b) The DSMP is also to include safe work method statements relating to\naccess and maintenance of each component in the maintenance\nschedule.\n(c) Signage is to be placed in v icinity of each component, identifying the\ncomponent to as it is referred in the DSMP (eg. OSD - 1), the reference to\nthe maintenance work method statement and maintenance routine\nschedule.\n(d) Designate areas inside the property in which the maintenance operation is\nto be undertaken for each component. Maintenance from the road reserve\nor public domain is not accepted. Areas are to be demarcated if required.\n(e) Locate a storage area for ma intenance components / tools to be stored on\nsite. The location is to be recorded in the DSMP.\nThe DSMP is to be prepared by a suitably qualified and practisi ng drainage\nengineer in co-operation with a workplace safety officer (or si milar qualified\npersonal) and all signage / linemar kings are to be implemented\nprior to the\nissue of any Occupation Certificate.\n201. Restriction as to User - Floodway. A restriction as to user is to be placed on\nthe property title to prevent any works which would result in the alteration of the\nground surface level or impose on overland flow due to stormwater runoff in the\n100ARI, such to adversely impact flood protection of the approv ed dwelling or\nhave an adverse impact on neighbouring properties. The terms of the restriction\nshall be generally in accordance with Council’s draft terms for provision for\noverland flow, to the satisfaction of Council and must be regis tered on the title\nof the property prior to the release of any Occupation Certificate.\n202. Positive Covenant(s) - Stormwater Management. A Positive Covenant must\nbe created on the property title(s ) pursuant to the relevant se ction of the\nConveyancing Act (1919), providing for the ongoing maintenance of the WSUD\ncomponents incorporated in the approved Stormwater Management s ystem.\nThis is to ensure that the dr ainage system will be maintained a nd operate as\napproved throughout the life of the development, by the owner o f the site(s).\nThe terms of the instrument are to be in accordance with the Council's standard\nterms for such systems, as specified in City of Ryde DCP 2014 - Part 8.4 (Title\nEncumbrances) - Section 7 and to the satisfaction of Council. The positive\ncovenant must be registered on the title prior to the release of any Occupation\nCertificate for development works for which the system(s) serve.\n203. Engineering Compliance Certificates. To ensure that all engineering facets\nof the development have been des igned and constructed to the ap propriate\nstandards, Compliance Certificates must be obtained for the fol lowing items\nand are to be submitted to the Accredited Certifier prior to th e release of any\nOccupation Certificate . All certification must b e issued by a qualified and\npractising civil engineer having experience in the area respect ive of the\ncertification unless stated otherwise.\n(a) Confirming that all component s of the parking areas contained inside the\nsite comply with the relevant components of AS 2890 and Council’s DCP\n2014 Part 9.3 (Parking Controls).\n(b) Confirming that the Stormw ater Management system (including any\nconstructed ancillary components such as onsite detention) servicing the\ndevelopment complies with Council’s DCP 2014 Part 8.2 (Stormwater and\nFloodplain Management) and associated annexures, and has been\nconstructed to function in accordance with all conditions of this consent\nrelating to the discharge of stormwater from the site.\n(c) Confirming that after compl etion of all construction work and landscaping,\nall areas adjacent the site, the site drainage system (including any on-site\ndetention system), and the trunk drainage system immediately\ndownstream of the subject site (next pit), have been cleaned of all sand,\nsilt, old formwork, and other debris.\n(d) Confirming that the footi ngs adjacent to drainage easements are founded\nbelow the zone of influence of this infrastructure, in accordance with\nCouncil’s DCP 2014 Part 8.2 (Stormwater and Floodplain Manageme\nnt)\nand associated annexures.\n(e) Confirming that erosion and s ediment control measures were\nimplemented during the course of construction and were in accordance\nwith the manual “Managing Urban Stormwater: Soils and Construction“\nby the NSW Department - Office of Environment and Heritage and\nCouncil’s DCP 2014 Part 8.1 (Construction Activities).\n(f) Certification from a suit ably qualified structural or geotechnical engineer\nconfirming that any temporary soil/ rock anchors installed into public\nroadway, have been de-stressed and are no longer providing any\nstructural support.\n(g) Compliance certificate from Council confirming that all external works in\nthe public road reserve and alteration to Council assets located in the\nproperty have been completed to Council’s satisfaction.\n204. Waste Room Approval. An authorised Council traffic engineer or waste officer\nis to ensure that the developm ent can be accessed and serviced by the\nnominated waste collection vehicle in accordance with the Waste Management\nPlan providing safe easy access to service the waste containers . A p p r o v a l\nmust be provided by City of Ryd e Council prior to the issue of the Occupation\nCertificate applying to the waste rooms.\n205. Garbage Services. Suitable arrangements must be made with the City of Ryde\nCouncil for the provision of gar bage services to the premises p rior to the issue\nof any Occupation Certificate . An inspection by a Council waste officer is\nrequired to ensure that the wast e facilities comply with the de velopment\napproval plans.\n206. Onsite Waste Collection - Positive Covenant. Where it is necessary for\nwaste collection vehicles to enter the property to service the waste containers,\nA Positive Covenant must be cr eated on the property title(s) pu rsuant to the\nrelevant section of the Conveyancing Act (1919), ensuring that future owners\nprovide and maintain the access driveway and loading bay accomm odating\nwaste collection services undertaken by Council. The terms of t he instrument\nare to be generally in accordanc e with the standard terms (avai lable from\nCouncil) and any amendments underta ken in accordance with the C ity of Ryde\nD C P 2 0 1 4 - P a r t 8 . 4 (Title Encumbrances ) - Section 7. The terms of the\ncovenant are to be to the satisfaction of Council prior to endo rsement and are\nto be registered on the title prior to the release of any Occupation Certificate.\nThe application to Council for endorsement of the positive cove nant must be\naccompanied by a Works-As-Executed plan of the service area ens uring there\nis adequate swept path and height c learances so as to accommoda te Council\nwaste vehicles. A swept path analysis may also be required to clarify this.\n207. Key access to waste rooms. Where there is a lockable door to access a bin\nroom or hardwaste storage room, the universal Council key shoul d be installed\nso the contractor can access the room for servicing bins or col lect the\nhousehold cleanup items.\n208. Pedestrian Corridor - Completion - The pedestrian link sha ll be constructed\nin accordance with the approved design prior to the issue of any Occupation\nCertificate for the Phase 1 works and at no cost to Council. Full public a ccess\nis to be available at all times over the pedestrian link follow ing the issue by\nCouncil of the Compliance Certificate for all public domain works.\n209. Public Access and Right of Way - Prior to the issue of any Occupation\nCertificate, a Right of Way (ROW) shall be created over the pedestrian lin k in\nfavour of Council for public access. Terms regarding the creati on of the ROW\nare to be submitted to and approved by Council prior to the lod gement at the\nLand and Property Information Office. Evidence regarding effec tive registration\nof the ROW shall be submitted to Council and the PCA prior to t he issue of the\nOccupation Certificate.\nThe terms of the Right of Way must ensure that:\n(i) The Pedestrian Link is acce ssible at all times to the Public;\n(ii) The Pedestrian Link will be adequately maintained by the occupier/ owner of\nthe site at all times;\n(iii) The Council is the only authority empowered to release, vary or modify the\nterms of the Public Access.\n210. Public Positive Covenant - Prior to the issue of any Occupation Certificate\nfor the development, a public positive covenant, pursuant to Se ction 88E of the\nConveyancing Act 1919, is to be created over the subject land i n order to\nensure that the registered owner of the land, at his / her / its own cost and risk:\n(i) maintains and repairs at all times that area of the subject land that has been\ndesignated as the privately owned, publicly accessible pedestrian link, to a\nstandard commensurate with Council’s standards for the maintenance of\nsuch facility;\n(ii) maintains at all times, public liability insurance for at least $20 million, with\nCouncil identified as an interested party in that insurance policy.\nThe Instrument that is to create the public positive covenant referred to in this\ncondition is to be submitted to and approved by Council prior to lodgement for\nregistration at the Land & Property Information Office.\nPrior to the issue of any Occupation Certificate the applicant is to submit to\nCouncil a certificate of currency for the above mentioned public liability\ninsurance.\n211. Public Domain Improvements and Infrastructure Works - Completio n - All\npublic domain improvements and in frastructure works shall be co mpleted to\nCouncil’s satisfaction, in acco rdance with the approved public domain plans\nand at no cost to the Council, prior to the issue of any Occupation Certificate.\n212. Restoration - Supervising Engineer’s Certificate - P r i o r t o t h e i s s u e o f a n y\nOccupation Certificate, the Applicant shall submit to Council a certificate from\nthe Supervising Engineer confirming that the fi nal restoration of disturbed road\nand footway areas for the purpose of connection to public utili ties, including\nrepairs of damaged infrastructu re and replacement of any redund ant vehicular\ncrossings as a result of the construction works associated with this development\nsite, have been completed in acco rdance with the Council’s stan\ndards and\nspecifications, and DCP2014 Part 8.5 Public Civil Works, or the Roads and\nMaritime Services’ standards and specifications, where applicable.\n213. Compliance Certificates - Street Lighting - Prior to the issue of any\nOccupation Certificate, the Applicant shall submit to Council, a Certificate of\nCompliance - Electrical Work (CCEW) from the Electrical Contractor, and\ncertification from a qualified Electrical Engineering consultan t confirming that\nthe street lighting in the public domain has been constructed in accordance with\nthe Council approved drawings and City of Ryde standards and specifications.\n214. Compliance Certificate - External Landscaping Works - Prior to the issue\nof any Occupation Certificate , the Applicant shall submit to Council,\ncertification from a qualified Landscape Architect confirming t hat the public\ndomain landscaping works have been constructed in accordance wi th the\nCouncil approved drawings and City of Ryde standards and specifications.\n215. Public Domain Works-as-Executed Plans - To ensure the public\ninfrastructure works are completed in accordance with the appro ved plans and\nspecifications, Works-as-Executed (WAE) Plans shall be submitte d to Council\nfor review and approval. The WAE Plans shall be prepared on a copy of the\napproved plans and shall be certified by a Registered Surveyor. All departures\nfrom the Council approved details shall be marked in red with p roper notations.\nAny rectifications required by Council shall be completed by the Developer prior\nto the issue of any Occupation Certificate.\nIn addition to the WAE Plans, a list of all infrastructure assets (new and\nimproved) that are to be handed over to Council shall be submitted in a form\nadvised by Council. The list shall include all the relevant quantities in order to\nfacilitate the registration of the assets in Council’s Asset Registers.\n216. Supervising Engineer Final Certificate - Prior to the issue of any\nOccupation Certificate , the Applicant shall submit to Council, a Final\nCertificate from the Supervisi ng Engineer confirming that the p ublic domain\nworks have been constructed in accordance with the Council appr oved\ndrawings and City of Ryde standar ds and specifications. The ce rtificate shall\ninclude commentary to support any variations from the approved drawings.\n217. Post-Construction Dilapidation Report - To ensure Council’s infrastructures are\nadequately protected a post-construction dilapidation report on the existing public\ninfrastructure in the vicinity of the completed development and along the travel\nroutes of all construction vehicles, up to 100m either side of the development site,\nis to be submitted to Council. T he report shall detail, but not be limited to, the\nlocation, description and photographic record of any observable defects to the\nfollowing infrastructure where applicable.\n(a) Road pavement,\n(b) Kerb and gutter,\n(c) Footpath,\n(d) Drainage pits and lintels,\n(e) Traffic signs, and\n(f) Any other relevant infrastructure.\nThe report shall include summary statement/s comparing the pre and post\nconstruction conditions of the public infrastructure. The repo\nrt is to be dated and\nsubmitted to, and accepted by Council’s City Works Directorate, prior to issue of the\nOccupation Certificate. The report shall be used by Council to compare with the\npre-construction dilapidation report, and to assess whether restoration works will be\nrequired prior to the issue of the Occupation Certificate.\nAll fees and charges associated with the review of the report shall be in accordance\nwith Council’s Schedule of Fees and Charges, and shall be paid at the time that the\nDilapidation Report is submitted.\n218. Decommissioning of Ground Anchors - Prior to the issue of any\nOccupation Certificate, the Applicant shall provide Council a certificate from a\nsuitably qualified Structural o r Geotechnical Engineer confirmi ng that all\ntemporary soil/ground anchors installed into the public road reserve, have been\ndecommissioned and are not transferring any structural loads in to the road\nreserve stratum.\n219. Final Inspection - Assets Handover - For the purpose of the handover of the\npublic infrastructure assets to Council, a final inspection sha ll be conducted in\nconjunction with Council’s Engineer from City Works Directorate following the\ncompletion of the external works. Defects found at such inspec tion shall be\nrectified by the Applicant prior to Council issuing the Complia nce Certificate for\nthe External Works. Additional inspections, if required, shall be subject to fees\npayable in accordance with Council’s Schedule of Fees & Charges at the time.\nA minimum 48 hours’ notice will be required when booking for th e final\ninspection.\n220. Compliance Certificate - Public D omain Works and Public Infrast ructure\nRestoration - Prior to the issue of any Occupation Certificate, a compliance\ncertificate shall be obtained from Council’s City Works Directo rate confirming\nthat all works in the road reserve including all public domain improvement\nworks, works for the pedestrian lin k and restoration of all inf rastructure assets\nthat have dilapidated as a result of the development works, hav e been\ncompleted to Council’s satisfaction and in accordance with the Council\napproved drawings. The applicant shall be liable for the paymen t of the fee\nassociated with the issuing of t his Certificate in accordance w ith Council’s\nSchedule of Fees and Charges at the time of issue of the Certificate.\n221. Engineering Condition - Public Domain Works - All civil works associated\nwith the pedestrian corridor and all other road works, kerb, gu tter, footpath,\nvehicular access, street lighting, bus shelter and stormwater drainage works for\nthis development site shall be c ompleted in accordance with Cou ncil’s\nspecifications and to the satisfaction of Council prior to the issue of any\nOccupation Certificate.\n222. Signage and Linemarking - External . A plan demonstrating the proposed\nsignage and line marking within Council’s Public Domain shall be prepared by a\nsuitably qualified person and subm itted to and approved by the Ryde Traffic\nCommittee prior to the issue of any Occupation Certificate.\nNote: The applicant is advised that the plan will require approval by the Ryde\nTraffic Committee if the proposal requires change in existing p arking conditions\nand hence, adequate time should be allowed for this process.\n223. Signage and Linemarking - Implementation . The applicant is to install all\nsignage and linemarking, as per the plan approved by the Ryde T raffic\nCommittee. These works are to be undertaken prior to the issue o f a n y\nOccupation Certificate.\n224. Drainage Works - Completion - All trunk drainage works shall be completed\nto Council’s satisfaction and at no cost to Council, in accorda nce with the\nrelevant conditions of this consent, Council approved construct ion drawings\nfrom condition “Detailed Design S ubmission - Trunk Drainage Wor ks” within\nthis consent, and generally in accordance with the approved co ncept plans\nidentified as “Drawing Numbers DAC002 Rev H, DAC003 Rev H, DAC0 04 Rev\nD, DAC005 Rev D, DAC006 Rev D,DAC007 Rev D, DAC010 Rev J, DAC01 1\nRev J, DAC012 Rev H, DAC013 Rev H, DAC014 Rev H, DAC015 Rev H,\nDAC023 Rev G, DAC024 Rev E, DAC050 Rev C, DAC070 Rev H Project\nNumber 16-428” and Flood Planning Assessment report (Rev H) as prepared\nby Calibre Professional Services Pty Ltd Dated 15 May 2019, pri or to the issue\nof any Occupation Certificate.\nThe Applicant shall obtain a written approval from Council’s City Works\nDirectorate confirming that this condition has been satisfied prior to the issue of\nany Occupation Certificate.\n225. Creation of a New Council Drainage Easement - An easement in favour of\nCouncil shall be created over t he proposed Council trunk draina ge system\nlocated within the site for the purpose of reconstruction and m aintenance of the\ntrunk drainage structures. The width of the easement shall be t aken as\nminimum 1.0 m from the outermo st external face of the drainage pipelines,\nculverts or pits. The total width of the easement shall be roun ded up to the next\nhighest 0.5 m. The easement must be centrally located over the trunk drainage\nsystem.\nThe wording of the dedication shall be submitted to, and approved by Council’s\nCity Works Directorate prior to lodgement at NSW Land Registry.\nThe easement shall be registered and a registered copy of the document shall\nbe submitted to and approved by Council prior to the issue of an Occupation\nCertificate.\n226. Floodway Signage - Permanent floodway signage (minimum two) including\ndepth indicators shall be inst alled along the western boundary adjacent to the\nproposed trunk drainage system wit hin the development site prio r to the issue\nof any Occupation Certificate . The wordings and installation location of the\nsignage shall be shown on plan prepared by a qualified engineer\nin accordance\nwith the Flood Planning Assessment report (Rev H) as prepared b y Calibre\nProfessional Services Pty Ltd Dated 15 May 2019 and approved by Council in\nwriting. The signage may be purchased from Council's Customer S ervice\nCentre at Ryde Civic Centre (Devlin Street, Ryde).\n227. Restriction to User - Floodway - To ensure unhindered passage of overland\nflow through the site, a restriction as to user is to be placed on the property title\nto prevent any works which would result in the alteration of th e ground surface\nlevel or impose on overland flow due to stormwater runoff in ex cess of the\ncapacity of the underground trunk d rainage system. The extent o f the identified\noverland flow path within the su bject site shall be shown on a scaled sketch,\nattached as an annexure to the request forms.\nThe terms of the restriction shall be submitted to, and approved by Council's\nCity Works Directorate prior to lodgement at NSW Land Registry Services. The\nInstrument shall be registered and a registered copy of the document shall be\nsubmitted to and approved by the consent authority prior to the issue of an\nOccupation Certificate.\n228. Positive Covenant - Water Sensitive Urban Design (WSUD) - A positive\ncovenant pursuant to the Convey ancing Act must be created on th e title of the\nproperty to prevent future modi fication or alteration without t he written consent\nof Council, and to ensure suitable maintenance is carried out.\nThe positive covenant shall detail the water sensitive urban design components\nwithin the proposed development. The wording of the Instrument shall be\nsubmitted to, and approved by Council's City Works Directorate prior to\nlodgement at NSW Land Registry. The Instrument shall be registered and a\nregistered copy of the document shall be submitted to and approved by the\nconsent authority prior to the issue of an Occupation Certificate/use of the\nbuilding.\n229. Maintenance (WSUD) - An Operational Management and Maintenance Report\nis required to be submitted to the Principle Certifying Authority prior to the issue\nof an Occupation Certificate to provide an outline of the proposed long term\noperational management and maintenance requirements of the Water Sensitive\nUrban Design (WSUD) features on the site. A schedule or timetab l e f o r t h e\nproposed regular inspection and m onitoring of the devices, main tenance\ntechniques, reporting and record keeping requirements and assoc iated\nrectification procedure shall be included in the report. Counci l recommends a\nvisual inspection at least 2 times per year. Inspection should be made not less\nthan 24 hours and not more than 72 hours after the cessation of rainfall if the\ntotal rainfall on any day exceeds 30mm.\n230. Flooding - Electrical Components - All electrical connections and flood\nsensitive equipment shall be l ocated above the 1% AEP (100 year ARI) flood\nlevel plus 500 mm freeboard. A certificate from a suitably qual\nified Engineer\n(registered on the NER of Engine ers Australia), or equivalent, shall be\nsubmitted to the Principal Cert ifying Authority stating complia nce with this\ncondition prior to the issue of the Occupation Certificate.\n231. Flooding - Building Components - Structural Design - A certificate from a\nsuitably qualified Chartered St ructural Engineer (registered on the NER of\nEngineers Australia), or equivalent, shall be provided to the P rincipal Certifying\nAuthority, prior to the issue of the Occupation Certificate , confirming the\nbuilding structure is able to withstand the forces of floodwaters having regard to\nhydrostatic pressure, hydrodynamic pressure, the impact of debr is and\nbuoyancy forces up to the Probable Maximum Flood (PMF) event.\n232. Flood Emergency Response Plan . A Detailed Flood Emergency Response\nPlan (FERP) is to be developed for the proposed residential building.\nThe FERP shall consider floods up to and including the Probable Maximum\nFlood (PMF). Implementation and maintenance of the FERP shall b e the\nresponsibility of building manage ment and all owners, tenants a nd users of the\nbuilding must be made aware of the FERP. FERP shall include det ails of the\nproposed ‘on-site’ refuge area. Permanent signage shall be inst alled in the\ncommon areas notifying the future occupants of the evacuation p rocedures and\nrefuge areas.\nDetails of the FERP shall be prepared by a suitably qualified C ivil Engineer\n(registered on the NER of Engineer s Australia), or equivalent, and to be\nsubmitted to Council for approval prior to issue of the Occupation Certificate.\n233. Flooding - Flood Impact Statement - The applicant shall comply with the\nrecommendations provided in the Flood Planning Assessment repor t prepared\nby Calibre Professional Services (Revision H, 15 May 2019).\nA certificate from a suitably qualified Drainage Engineer (registered on the NER\nof Engineers Australia), or equiva lent, shall be submitted to t he Principal\nCertifying Authority stating compliance with these recommendations prior to the\nissue of the Occupation Certificate.\n234. Drainage Works - Post Cons truction Certifications - Following completion\nof the final stage of the drainage and associated works and prior to the issue of\nthe Occupation Certificate, the applicant shall submit all certifications from the\nSupervising Engineer for each hol d point inspection required fo r the drainage\nworks, as outlined in the condition for “Hold Points during con struction -\nDrainage Works”, to Council’s Cit y Works Directorate for accept ance and\nwritten approval.\nThe certificates shall contain photographs of the completed wor ks and\ncommentary of the inspected works, including any deficiencies a nd\nrectifications that were undertaken.\n235. Certification - Structures / Excavations near Council’s Easemen ts - A\ncertification from a suitably qua lified Chartered Structural En gineer (registered\non the NER of Engineers Australia), or equivalent, stating that all footings and\nstructures adjacent to Council’s pipeline and/or easement have been\nconstructed at least 100mm below the invert of the Council’s pi pe unless the\nfootings are placed on competent bedrock is required. All struc tural support\nelements adjacent to the existi ng 2400 mm drainage pipeline mus t be founded\noutside the easement and zone of i nfluence to provide stability to both the\nstructure and drainage system particularly during maintenance operations.\nCertification is to be provided to the Principal Certifying Aut hority (PCA), and a\ncopy provided to Council, prior to issue of any Occupation Certificate.\n236. Works-As-Executed Drawings - Trunk Drainage Works - Prior to the issue\nof an Occupation Certificate, W orks-As-Executed Drawings prepar ed by a\nregistered surveyor for all new d rainage works shall be submitt ed to and\napproved by Council’s Stormwater E ngineer. All departures from the Council\napproved details shall be marked in red with proper notations. A n y\nrectifications required by Counc il shall be completed by the De veloper prior to\nthe issue of any Occupation Certificate.\n237. Post-Construction CCTV Report - To ensure Council’s existing and new\nstormwater infrastructures are adequately protected, without da mages and the\nconstruction has been completed to Council’s satisfaction, a po st-construction\nCCTV report on the Council’s existing stormwater drainage pipeline and all new\nstormwater drainage works thro ugh the proposed development site and on\nTalavera Road is to be submitted to Council.\nAn electronic closed circuit t elevision report (track mounted C CTV camera\nfootage) prepared by an accredit ed operator (with a certificate of attainment in\nNWP331A Perform Conduit Conditi on Evaluation) that assesses the condition\nof the existing drainage line adj acent to the site is required. The report is to be\ndated and submitted to, and accepted by Council’s City Works Directorate, prior\nto issue of the Occupation Certificate.\nThe report shall be used by Council to compare with the pre-construction CCTV\nfootage report, and to assess whether any rectification works will be required to\nCouncil’s satisfaction at no cost to Council. The applicant shall obtain written\napproval from a Council Engineer prior to the issue of the Occupation\nCertificate.\nThe applicant shall contact Council’s Stormwater and Catchments section to\nobtain a map of Council’s existing stormwater network in the vicinity prior to\nconducting the CCTV survey.\n238. Compliance Certificate - Trunk Drainage Works - Prior to the issue of any\nOccupation Certificate , a compliance certificate shall be obtained from\nCouncil’s City Works Directorate confirming that all trunk drai nage and\nassociated restoration works have been completed to Council’s satisfaction and\nin accordance with the Council approved drawings. The applicant shall be liable\nfor the payment of the fee asso ciated with the issuing of this Certificate in\naccordance with Council’s Schedule of Fees and Charges at the t ime of issue\nof the Certificate.\n239. Final Inspection - Trunk Drainage Assets Handover - For the purpose of the\nhandover of the trunk drainage assets to Council, a final inspe ction shall be\nconducted in conjunction with Counc il’s Engineer from City Work s Directorate\nfollowing the completion of the trunk drainage works. Defects found at such\ninspection shall be rectified by the Applicant prior to Council issuing the\nCompliance Certificate for the trunk drainage Works. Additiona l inspections, if\nrequired, shall be subject to fees payable in accordance with C ouncil’s\nSchedule of Fees & Charges at the time.\n240. New Council Easement over proposed Trunk Drainage system - An\neasement in favour of Council is required over the proposed tru nk drainage\nsystem located within the site for the purpose of maintenance a nd\nreconstruction of the trunk drainage structures. The width of the easement shall\nbe taken as minimum 1.0 m from the outermost external face of t he drainage\npipelines, culverts or pits. The total width of the easement sh all be rounded up\nto the next highest 0.5 m. The easement must be centrally locat ed over the\ntrunk drainage system.\nUpdated architectural and civil pl ans clearly showing the propo sed easement\nshall be submitted to Council for approval prior to the issue o f any Occupation\nCertificate.","stage":"during_work","stage_basis":"heading","page":41}]});
